<?php use Namira\PublicPresentation as P;$humanTitle=P::imageTitle($im); ?>
<div class="panel image-detail"><a href="<?= e(url('media',['id'=>$im['id'],'size'=>'large'])) ?>"><img class="preview" src="<?= e(url('media',['id'=>$im['id'],'size'=>'large'])) ?>" alt="<?= e($humanTitle) ?>"></a><div><p class="muted">آرشیو تصاویر نامیرا</p><?php if($humanTitle!==''): ?><h1><?= e($humanTitle) ?></h1><?php endif ?><p class="hint"><?= fa($im['width'].' × '.$im['height']) ?> · <?= e($im['mime']) ?> · <?= fa(round($im['bytes']/1048576,2)) ?> مگابایت</p>
<?php if($creators): ?><section class="image-credits"><h2>پدیدآورندگان</h2><?php foreach($creators as $creator): ?><p><?= e($creator['creator_role']) ?>: <?php if($creator['public_visible']&&!$creator['archived']): ?><a href="<?= e(url('artist',['id'=>$creator['artist_id']])) ?>"><?= e($creator['credit_name']) ?></a><?php else: ?><?= e($creator['credit_name']) ?><?php endif ?></p><?php endforeach ?></section><?php elseif(P::meaningful($im['designer']??'')): ?><p><?= e($im['designer']) ?></p><?php endif ?>
<?php foreach(['description'=>'','source_text'=>'منبع: '] as $key=>$label):if(!P::meaningful($im['publication'][$key]??null))continue; ?><p class="prose"><?= e($label).nl2br(e($im['publication'][$key])) ?></p><?php endforeach ?>
<?php if(P::meaningful($im['license_text']??null)): ?><p class="prose"><?= e($im['license_text']) ?></p><?php endif ?>
<div class="image-actions"><?php if(!empty($im['download_allowed'])): ?><a class="primary" href="<?= e(url('download',['id'=>$im['id']])) ?>">↓ دانلود رایگان فایل اصلی</a><?php else: ?><p class="notice">دانلود اصل این رسانه با مجوز فعلی فعال نیست.</p><?php endif ?></div>
<nav class="related-people" aria-label="پرونده شهید"><?php foreach($people?:[['id'=>$im['martyr_id'],'display_name'=>$im['display_name']??trim($im['first_name'].' '.$im['last_name'])]] as $person): ?><a class="outline" href="<?= e(url('profile',['id'=>$person['id']])) ?>">شهید <?= e(($person['display_name']??'')?:trim(($person['first_name']??'').' '.($person['last_name']??''))) ?></a><?php endforeach ?></nav></div></div>